from pathlib import Path
for loc,title,bullets in [
('zh-TW/chapters/CH14-chapter-14.md','參考資料',['[R101] [Bruce Block, *The Visual Story*, Routledge](https://www.routledge.com/The-Visual-Story-Creating-the-Visual-Structure-of-Film-TV-and-Digital-Media/Block/p/book/9781315794839)（出版社頁；未查全書）。','[R102] [Unreal Engine, What is virtual production?](https://www.unrealengine.com/explainers/virtual-production/what-is-virtual-production?lang=en)（官方說明頁）。','[R103] [Blender Manual, Storyboarding](https://docs.blender.org/manual/en/latest/video_editing/storyboarding/index.html)（官方文件，版本敏感）。','[R104] [American Cinematographer, Ben Davis interview](https://theasc.com/article/three-billboards-interview-ben-davis/)（《三塊廣告牌》製作訪談）。','[R105] [American Cinematographer, Steven Spielberg on *Indiana Jones and the Temple of Doom*](https://theasc.com/article/spielberg-temple-of-doom/)（1984 訪談重刊）。','[R106] [Blender Studio, Storyboard workflow](https://studio.blender.org/tools/artist-guide/pre-production/storyboard)（單一工作室案例）。']),
('en-US/chapters/CH14-chapter-14.md','References',['[R101] [Bruce Block, *The Visual Story*, Routledge](https://www.routledge.com/The-Visual-Story-Creating-the-Visual-Structure-of-Film-TV-and-Digital-Media/Block/p/book/9781315794839) (publisher page; full text not consulted).','[R102] [Unreal Engine, What is virtual production?](https://www.unrealengine.com/explainers/virtual-production/what-is-virtual-production?lang=en) (official explainer).','[R103] [Blender Manual, Storyboarding](https://docs.blender.org/manual/en/latest/video_editing/storyboarding/index.html) (official, version-sensitive).','[R104] [American Cinematographer, Ben Davis interview](https://theasc.com/article/three-billboards-interview-ben-davis/) (production interview).','[R105] [American Cinematographer, Steven Spielberg on *Indiana Jones and the Temple of Doom*](https://theasc.com/article/spielberg-temple-of-doom/) (1984 interview republished).','[R106] [Blender Studio, Storyboard workflow](https://studio.blender.org/tools/artist-guide/pre-production/storyboard) (one studio’s workflow).'])]:
 p=Path('content')/loc; s=p.read_text(encoding='utf-8'); marker='### '+title+'\n'; i=s.rfind(marker); assert i>=0; end=s.find('\n## ',i+len(marker)); end=len(s) if end<0 else end; s=s[:end].rstrip()+'\n\n'+'\n'.join('- '+x for x in bullets)+'\n'+s[end:]; p.write_text(s,encoding='utf-8')
